import {
  JupyterFrontEnd,
  JupyterFrontEndPlugin
} from '@jupyterlab/application';

import {
  INotebookTracker,
  NotebookActions
} from '@jupyterlab/notebook';


interface MathAIMessage {
  type: string;
  text?: string;
}


interface MathAIResponse {
  type: string;
  success: boolean;
  error?: string;
}


const MATHAI_ORIGIN = 'http://127.0.0.1:8000';


function sendToMathAI(response: MathAIResponse): void {

  window.parent.postMessage(
    response,
    MATHAI_ORIGIN
  );

}


const plugin: JupyterFrontEndPlugin<void> = {

  id: 'mathai-jupyter-bridge',

  description:
    'Bridge between MathAI and JupyterLab.',

  autoStart: true,

  requires: [INotebookTracker],


  activate: (
    app: JupyterFrontEnd,
    tracker: INotebookTracker
  ) => {


    console.log(
      'MathAI Jupyter bridge loaded.'
    );


    /*
     * Cmd+Shift+L
     *
     * Listen during the capture phase so that
     * JupyterLab's own keyboard handling does not
     * prevent us from seeing the event.
     */

    document.addEventListener(
      'keydown',
      event => {

        if (
          event.metaKey &&
          event.shiftKey &&
          event.key.toLowerCase() === 'l'
        ) {

          event.preventDefault();

          event.stopPropagation();


          window.parent.postMessage(
            {
              type:
                'mathai-open-python-prompt'
            },
            MATHAI_ORIGIN
          );

        }

      },
      true
    );


    /*
     * Listen for commands from MathAI.
     */

    window.addEventListener(
      'message',
      event => {

        if (
          event.origin !== MATHAI_ORIGIN
        ) {

          return;

        }


        const message =
          event.data as MathAIMessage;


        if (
          !message ||
          message.type !==
            'mathai-insert-text'
        ) {

          return;

        }


        try {


          if (
            typeof message.text !==
            'string'
          ) {

            throw new Error(
              'No text was provided.'
            );

          }


          const panel =
            tracker.currentWidget;


          if (!panel) {

            throw new Error(
              'No notebook is currently open.'
            );

          }


          const notebook =
            panel.content;


          if (
            notebook.activeCellIndex < 0
          ) {

            throw new Error(
              'No active cell.'
            );

          }


          /*
           * Create a new code cell immediately
           * below the active cell.
           */

          NotebookActions.insertBelow(
            notebook
          );


          const newCell =
            notebook.activeCell;


          if (!newCell) {

            throw new Error(
              'Could not access the new cell.'
            );

          }


          newCell.model.sharedModel.setSource(
            message.text
          );


          sendToMathAI({

            type:
              'mathai-insert-result',

            success: true

          });


        } catch (error) {


          console.error(
            'MathAI insertion failed:',
            error
          );


          sendToMathAI({

            type:
              'mathai-insert-result',

            success: false,

            error:
              String(error)

          });

        }

      }
    );

  }

};


export default plugin;